$target = Join-Path $PSScriptRoot '..\admin-panel\app\quran\page.tsx'
$source = Get-Content -LiteralPath $target -Raw -Encoding utf8
$source = $source.Replace('setPronunciation(row.localizedNames?.[language]?.pronunciation||"");setMeaning(row.localizedNames?.[language]?.meaning||"");setSource(row.translationMeta?.[language]?.source||"");setReviewedBy(row.translationMeta?.[language]?.reviewedBy||"");setValues(Object.fromEntries((row.ayahs||[]).map((a:any)=>[a.numberInSurah,a.translations?.[language]||""])))', 'setPronunciation(language==="en"?(row.englishName||""):(row.localizedNames?.[language]?.pronunciation||""));setMeaning(language==="en"?(row.englishNameTranslation||""):(row.localizedNames?.[language]?.meaning||""));setSource(language==="en"?"English base Quran dataset":(row.translationMeta?.[language]?.source||""));setReviewedBy(language==="en"?"Protected base content":(row.translationMeta?.[language]?.reviewedBy||""));setValues(Object.fromEntries((row.ayahs||[]).map((a:any)=>[a.numberInSurah,language==="en"?(a.translations?.en||a.translation||""):(a.translations?.[language]||"")])))')
$source = $source.Replace('{(surahs.find(s=>s.number===surahNo)?.translationProgress?.[language]||0)>0?<em>{"\u2713"} SAVED</em>', '{(language==="en"||(surahs.find(s=>s.number===surahNo)?.translationProgress?.[language]||0)>0)?<em>{"\u2713"} SAVED</em>')
Set-Content -LiteralPath $target -Value $source -NoNewline -Encoding utf8
